import { useNavigate } from "@tanstack/react-router";
import { ArrowLeft } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/**
 * One centered column width for every agent sub-tab (index + create/detail), so
 * no tab reads wider than its neighbors. Wrap each tab's content in this instead
 * of hand-writing `mx-auto w-full max-w-3xl` per page. Pass `className` to widen
 * (e.g. permissions matrix uses max-w-6xl).
 */
export function AgentTabShell({
	children,
	className,
}: {
	children: ReactNode;
	className?: string;
}) {
	return (
		<div className={cn("mx-auto w-full max-w-3xl pb-6", className)}>
			{children}
		</div>
	);
}

export function AgentSubpageShell({
	owner,
	agentId,
	children,
	showBack,
	backLabel,
	backTo,
	title,
	className,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
	backLabel: string;
	backTo: string;
	/** When set, a centered sticky header (title + gutter back arrow) owns the
	 *  page header — the detail form should NOT render its own title. */
	title?: ReactNode;
	/** Override shell width (default max-w-3xl). */
	className?: string;
}) {
	const navigate = useNavigate();

	const goBack = () => {
		void navigate({
			to: backTo,
			params: { owner, agentId },
		});
	};

	return (
		<div className={cn("mx-auto w-full max-w-3xl pb-8", className)}>
			{title ? (
				<>
					<AgentSubpageHeader
						title={title}
						onBack={goBack}
						backLabel={backLabel}
					/>
					{children}
				</>
			) : showBack ? (
				<WithBackGutter onBack={goBack} backLabel={backLabel}>
					{children}
				</WithBackGutter>
			) : (
				children
			)}
		</div>
	);
}

/**
 * Shared back affordance for agent sub-pages: an icon-only button in a left
 * gutter, top-aligned with the page title so it shares the title's row instead
 * of taking its own, and with no text label (which just repeated the section
 * name — the name rides `aria-label` for screen readers). Use this anywhere a
 * detail/create page needs a "back to <section>" control so every tab matches.
 */
export function WithBackGutter({
	onBack,
	backLabel,
	children,
}: {
	onBack: () => void;
	backLabel: string;
	children: ReactNode;
}) {
	// The arrow lives in the left margin (absolute, `right-full`) so it doesn't
	// indent the content — the page body stays full-width and centered under the
	// tab bar, with the arrow hanging in the gutter, top-aligned with the title.
	return (
		<div className="relative">
			<Button
				type="button"
				variant="ghost"
				size="icon"
				className="absolute right-full top-0 mr-1 size-8 text-muted-foreground hover:text-foreground"
				aria-label={`Back to ${backLabel}`}
				onClick={onBack}
			>
				<ArrowLeft className="h-4 w-4" />
			</Button>
			{children}
		</div>
	);
}

/**
 * Centered, sticky sub-page header for agent detail views: the item title sits
 * centered under the agent tab bar (matching the centered agent header), with a
 * back arrow pinned in the left gutter so it doesn't pull the title off-center.
 * Stays put while the page body scrolls.
 */
export function AgentSubpageHeader({
	title,
	onBack,
	backLabel,
}: {
	title: ReactNode;
	onBack: () => void;
	backLabel: string;
}) {
	return (
		<div className="sticky top-0 z-10 mb-2 bg-background py-2">
			<div className="flex items-center justify-center gap-1">
				<Button
					type="button"
					variant="ghost"
