import { ChevronRight, Search } from "lucide-react";
import type { ReactNode } from "react";
import { CatalogBadges } from "@/components/agents/catalog-badges";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";

export interface CatalogPickerItem {
	key: string;
	name: string;
	description: string;
	badges: string[];
}

/** 4-col catalog card grid — simple tiles or connector-picker cards. */
export function CatalogCardGridSkeleton({
	count = 4,
	variant = "simple",
}: {
	count?: number;
	variant?: "simple" | "connector";
}) {
	return (
		<div
			className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-4"
			role="status"
			aria-label="Loading catalog"
		>
			{Array.from({ length: count }).map((_, i) =>
				variant === "connector" ? (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton cards
						key={i}
						className="space-y-2 rounded-lg border bg-card p-3"
					>
						<div className="flex items-center gap-2">
							<Skeleton className="h-8 w-8 shrink-0 rounded-lg" />
							<Skeleton className="h-3.5 w-24 rounded" />
						</div>
						<Skeleton className="h-3 w-full rounded" />
						<Skeleton className="h-3 w-2/3 rounded" />
					</div>
				) : (
					<Skeleton
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton cards
						key={i}
						className="min-h-[5.5rem] w-full rounded-lg"
					/>
				),
			)}
		</div>
	);
}

/** Catalog search + card grid while template/provider/skill catalogs load. */
export function CatalogPickerSkeleton({
	count = 4,
	withSearch = true,
}: {
	count?: number;
	withSearch?: boolean;
}) {
	return (
		<div className="space-y-3" role="status" aria-label="Loading catalog">
			{withSearch ? <Skeleton className="h-9 w-full rounded-md" /> : null}
			<CatalogCardGridSkeleton count={count} />
		</div>
	);
}

export function CatalogPicker({
	items,
	searchQuery,
	onSearchChange,
	onSelect,
	emptyMessage,
	searchPlaceholder = "Search...",
	searchAriaLabel = "Search catalog",
	renderTitle,
}: {
	items: CatalogPickerItem[];
	searchQuery: string;
	onSearchChange: (value: string) => void;
	onSelect: (item: CatalogPickerItem) => void;
	emptyMessage?: string;
	searchPlaceholder?: string;
	searchAriaLabel?: string;
	renderTitle?: (item: CatalogPickerItem) => ReactNode;
}) {
	return (
		<div className="space-y-3">
			<div className="relative">
				<Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
				<Input
					aria-label={searchAriaLabel}
					placeholder={searchPlaceholder}
					value={searchQuery}
					onChange={(e) => onSearchChange(e.target.value)}
					className="pl-9"
				/>
			</div>
			{items.length === 0 ? (
				<p className="py-4 text-center text-sm text-muted-foreground">
					{emptyMessage ?? `No items match "${searchQuery}"`}
				</p>
			) : (
				<div className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-4">
					{items.map((item) => (
						<button
							key={item.key}
							type="button"
							className="flex h-full flex-col gap-2 rounded-lg bg-card p-3 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground"
							onClick={() => onSelect(item)}
						>
							<div className="flex items-start gap-2">
								<div className="min-w-0 flex-1">
									{renderTitle ? (
										renderTitle(item)
									) : (
										<span className="text-sm font-medium">{item.name}</span>
									)}
								</div>
								<ChevronRight className="mt-1 h-4 w-4 shrink-0 text-muted-foreground" />
							</div>
							<p className="line-clamp-2 text-xs text-muted-foreground">
								{item.description}
							</p>
							<CatalogBadges badges={item.badges} />
						</button>
					))}
				</div>
			)}
		</div>
	);
}

import type { ViewTemplateTab } from "@/lib/api";
import type { JsonTemplate } from "@/lib/json-renderer/types";
import type { EntityViewMode } from "./entity-view-resolution";

/**
 * Table: a single `entity-table` node. All table behavior (sorting, linked/enum/
 * date/currency formatting, relationship/derived/parent/stat columns, pagination
 * footer) lives in the registered EntityTableView; the panel hands it a single
 * memoized `tableState` object. Static shape ⇒ module-level constant.
 */
export const tableTemplate: JsonTemplate = {
	version: 1,
	root: {
		type: "entity-table",
		props: { state: "{{tableState}}" },
	},
};

/**
 * Board: a single `entity-board` node. Data props ride a bound `state` object;
 * the write is wired as the `updateEntity` action. All dnd/grouping/rollback
 * logic lives in the registered EntityBoardView. Static shape ⇒ module constant.
 */
export const boardTemplate: JsonTemplate = {
	version: 1,
	root: {
		type: "entity-board",
		props: { state: "{{boardState}}", onUpdate: "@updateEntity" },
	},
};

// Built-in list-view templates. Each returns a JsonTemplate ({version:1, root})
// that the entity list panel feeds to <JsonRenderer> along with the app-level
// entityRendererComponents. Board and Table are single registered-component
// nodes (their heavy logic lives in the component); Gallery is pure DSL over a
// prepared `galleryItems` array.
//
// The panel is responsible for shaping `rendererData` to match what each
// template binds — see EntityTypeListPanel.

/**
 * Gallery: a responsive grid of entity cards. Expressed in pure DSL — it loops
 * `galleryItems` (each `{ entity, subtitle }`, pre-parsed by the panel so the
 * template never touches a stringified metadata blob) and renders an
 * entity-link card wrapping the avatar monogram, the name, and an optional
 * subtitle. A truncation notice and a dashed "Add" tile are conditional.
 *
 * Static shape ⇒ memoized at module level.
 */
export const galleryTemplate: JsonTemplate = {
	version: 1,
	root: {
		type: "div",
		props: { className: "space-y-3" },
		children: [
			{
				type: "if",
				condition: "isTruncated",
				// biome-ignore lint/suspicious/noThenProperty: "then" is the DSL conditional branch, not a thenable.
				then: {
					type: "p",
					props: { className: "text-xs text-muted-foreground" },
					children: [{ type: "data", path: "truncationNotice" }],
				},
			},
			{
				type: "div",
				props: {
					className:
						"grid grid-cols-[repeat(auto-fill,minmax(200px,1fr))] gap-3",
				},
				children: [
					{
						type: "each",
						items: "galleryItems",
						as: "item",
						render: {
							type: "entity-link",
							props: {
								entity: "{{item.entity}}",
								owner: "{{owner}}",
								className:
									"flex flex-col items-center gap-1 rounded-lg border bg-card p-4 text-center transition-colors hover:border-primary/50",
							},
							children: [
								{
									type: "entity-avatar",
									props: {
										metadata: "{{item.metadata}}",
										metadataSchema: "{{schema}}",
										name: "{{item.entity.name}}",
										typeIcon: "{{entityTypeIcon}}",
										initialsFallback: true,
										className: "mb-2 h-14 w-14 text-lg",
									},
								},
								{
									type: "span",
									props: { className: "font-medium leading-tight" },
									children: [{ type: "data", path: "item.entity.name" }],
								},
								{
									type: "if",
									condition: "item.hasSubtitle",
									// biome-ignore lint/suspicious/noThenProperty: "then" is the DSL conditional branch, not a thenable.
									then: {
										type: "span",
										props: {
											className: "text-xs text-muted-foreground leading-snug",
										},
										children: [{ type: "data", path: "item.subtitle" }],
									},
								},
							],
						},
					},
					{
						type: "if",
						condition: "canCreate",
						// biome-ignore lint/suspicious/noThenProperty: "then" is the DSL conditional branch, not a thenable.
						then: {
							type: "button",
							props: {
								type: "button",
								onClick: "@openCreate",
								className:
									"flex flex-col items-center justify-center gap-2 rounded-lg border border-dashed p-4 text-sm text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground",
							},
							children: [{ type: "data", path: "addLabel" }],
						},
					},
				],
			},
		],
	},
};

/** One entry in the list view switcher: a built-in or an authored template. */
export interface EntityView {
	/** A built-in EntityViewMode, or an authored `custom:<tab_name>`. */
	id: string;
	label: string;
	/** true for the three built-ins; false for authored type-level templates. */
	isBuiltIn: boolean;
	/** Present only for built-ins (drives the switcher icon). */
	builtInMode?: EntityViewMode;
	template: JsonTemplate;
	/** Data bundle bound by the template. */
	data: Record<string, unknown>;
}

/**
 * The switcher's views, in order: the built-ins this type supports, then any
 * authored type-level templates (their `data_sources` already run server-side).
 * A pure function so the composition is unit-testable — labels/icons for the
 * built-ins are applied by the caller from VIEW_META.
 *
 * NB: authored templates are handed the SAME `actions.updateEntity` as built-ins
 * (the server is the single write trust boundary; there is no frontend gate).
 */
export function buildEntityViews(opts: {
	canShowBoard: boolean;
	canShowGallery: boolean;
	authoredTemplates: ViewTemplateTab[];
	/** Built-in data bundle; authored views overlay their data_sources onto it. */
	builtinData: Record<string, unknown>;
	/** Human labels for the three built-ins (from VIEW_META). */
	builtInLabels: Record<EntityViewMode, string>;
}): EntityView[] {
	const {
		canShowBoard,
		canShowGallery,
		authoredTemplates,
		builtinData,
		builtInLabels,
	} = opts;

	const builtInModes: EntityViewMode[] = [
		"table",
		...(canShowBoard ? (["board"] as const) : []),
		...(canShowGallery ? (["gallery"] as const) : []),
	];
	const builtInTemplate: Record<EntityViewMode, JsonTemplate> = {
		table: tableTemplate,
		board: boardTemplate,
		gallery: galleryTemplate,
	};

	const builtIns: EntityView[] = builtInModes.map((mode) => ({
		id: mode,
		label: builtInLabels[mode],
		isBuiltIn: true,
		builtInMode: mode,
		template: builtInTemplate[mode],
		data: builtinData,
	}));

	const authored: EntityView[] = authoredTemplates.map((tab) => ({
		id: `custom:${tab.tab_name}`,
		label: tab.tab_name,
		isBuiltIn: false,
		template: { version: 1, root: tab.json_template } as JsonTemplate,
		// Authored data_sources overlay the built-in bundle so an authored
		// template can still reach `entities`/`owner`/etc. if it references them.
		data: { ...builtinData, ...(tab.template_data ?? {}) },
	}));

	return [...builtIns, ...authored];
}

