import { createFileRoute, Link } from "@tanstack/react-router";
import { useState } from "react";
import { DeviceConnect } from "@/components/devices/device-connect";
import {
  DeviceStatusDot,
  deviceName,
  inferredPlatform,
  PlatformIcon,
} from "@/components/devices/device-display";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useDevices } from "@/lib/api/connections";

export const Route = createFileRoute("/$owner/infrastructure/devices/")({
  component: DevicesTab,
});

/**
 * Devices tab: your paired Mac / Chrome extension / CLI as runtimes. Devices are
 * user-owned and private ("Yours") — they follow you across workspaces — so they
 * carry that badge even on this org-scoped page.
 */
function DevicesTab() {
  const { owner } = Route.useParams();
  const { data: devices = [], isLoading } = useDevices();
  const [adding, setAdding] = useState(false);

  return (
    <div className="max-w-3xl space-y-4">
      <p className="text-sm text-muted-foreground">
        Your Mac, browser extension, or CLI — they run device-bound connectors
        and follow you across every workspace.
      </p>
      {!adding ? (
        <Button
          variant="outline"
          size="sm"
          className="h-8 text-xs"
          onClick={() => setAdding(true)}
        >
          Add a device
        </Button>
      ) : null}

      {isLoading ? (
        <div className="overflow-hidden rounded-lg border">
          {Array.from({ length: 2 }).map((_, i) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
              key={i}
              className={`flex items-center gap-3 px-3 py-2 ${i === 1 ? "" : "border-b"}`}
            >
              <Skeleton className="h-4 w-4 rounded-sm" />
              <Skeleton className="h-4 max-w-[12rem] flex-1" />
            </div>
          ))}
        </div>
      ) : devices.length > 0 ? (
        <div className="overflow-hidden rounded-lg border">
          {devices.map((device, idx) => (
            <Link
              key={device.id}
              to="/$owner/infrastructure/devices/$deviceId"
              params={{ owner, deviceId: device.id }}
              className={`flex items-center gap-3 px-3 py-2 hover:bg-accent/40 ${idx === devices.length - 1 ? "" : "border-b"}`}
            >
              <PlatformIcon platform={inferredPlatform(device)} />
              <span className="min-w-0 flex-1 truncate text-sm font-medium">
                {deviceName(device)}
              </span>
              <span className="rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
                Yours · private
              </span>
              <DeviceStatusDot online={device.online} />
            </Link>
          ))}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground">No devices connected.</p>
      )}

      {adding ? (
        <DeviceConnect owner={owner} onClose={() => setAdding(false)} />
      ) : null}
    </div>
  );
}

