	connector: ConnectorDefinitionItem;
	oauthMethod: OAuthMethod;
	appProfile: AuthProfileItem | null;
	accounts: AuthProfileItem[];
	connections: ConnectionItem[];
	isLoading: boolean;
	refetchProfiles: () => void;
	refetchConnections: () => void;
}) {
	const createAuthProfile = useCreateAuthProfile();
	const createConnection = useCreateConnection();
	const reconnect = useReconnectAuthProfile();
	const [error, setError] = useState<string | null>(null);

	const openOAuthPopup = (connectUrl: string) => {
		const popup = window.open(connectUrl, "_blank", "noopener,noreferrer");
		const refreshOnFocus = () => {
			void refetchProfiles();
			void refetchConnections();
			window.removeEventListener("focus", refreshOnFocus);
		};
		window.addEventListener("focus", refreshOnFocus);
		if (popup) {
			const interval = window.setInterval(() => {
				if (popup.closed) {
					window.clearInterval(interval);
					refreshOnFocus();
				}
			}, 500);
		}
	};

	const handleConnectAccount = async () => {
		if (!appProfile) {
			setError("Ask an admin to add a workspace OAuth app first.");
			return;
		}
		setError(null);
		try {
			const profileResult = await createAuthProfile.mutateAsync({
				connector_key: connector.key,
				profile_kind: "oauth_account",
				display_name: `${connector.name} account`,
				requested_scopes: buildRequestedOAuthScopes(oauthMethod, []),
			});
			const accountSlug =
				profileResult.auth_profile?.slug ?? profileResult.pending_slug;
			if (!accountSlug)
				throw new Error("OAuth account profile was not created");
			await createConnection.mutateAsync({
				connector_key: connector.key,
				auth_profile_slug: accountSlug,
				app_auth_profile_slug: appProfile.slug,
			});
			if (profileResult.connect_url) openOAuthPopup(profileResult.connect_url);
			void refetchProfiles();
			void refetchConnections();
		} catch (err) {
			setError(
