	// OAuth app exists, so with no app the primary action must be "add the app"
	// (which lives in the OAuth-apps section below), not a Connect button that
	// would just error. Once an app is configured, the CTA becomes Connect.
	const needsApp = !appProfile;
	return (
		<div className="space-y-3">
